import { Buffer } from 'node:buffer';

export type ParseResult =
  | { valid: true; token: string }
  | { valid: false; reason: 'missing' | 'malformed' | 'expired' };

const BEARER_PATTERN = /^Bearer\s+(\S+)$/i;

function readExpClaim(token: string): number | null {
  try {
    const json: unknown = JSON.parse(
      Buffer.from(token, 'base64url').toString('utf8'),
    );
    if (typeof json === 'object' && json !== null && 'exp' in json) {
      const exp: unknown = json.exp;
      if (typeof exp === 'number') {
        return exp;
      }
    }
  } catch {
    // Token is not decodable base64url JSON; no exp claim is readable.
  }
  return null;
}

export function parseAuthHeader(header: string, nowMs: number): ParseResult {
  const trimmed = header.trim();
  if (trimmed === '') {
    return { valid: false, reason: 'missing' };
  }

  const match = BEARER_PATTERN.exec(trimmed);
  if (match === null) {
    return { valid: false, reason: 'malformed' };
  }

  const token = match[1];
  if (typeof token !== 'string') {
    return { valid: false, reason: 'malformed' };
  }

  const exp = readExpClaim(token);
  if (exp !== null && exp * 1000 <= nowMs) {
    return { valid: false, reason: 'expired' };
  }

  return { valid: true, token };
}

export function describeParseResult(result: ParseResult): string {
  if (result.valid) {
    return `valid token: ${result.token}`;
  }
  switch (result.reason) {
    case 'missing':
      return 'authorization header is missing';
    case 'malformed':
      return 'authorization header is malformed';
    case 'expired':
      return 'token is expired';
    default:
      return assertNever(result);
  }
}

function assertNever(value: never): never {
  throw new Error(`Unhandled ParseResult variant: ${JSON.stringify(value)}`);
}
